// statePackedBlob is every global state's packed property values,
// uint32 little-endian in state-id order. Decoded into statePacked.
const statePackedBlob = ""

// statePacked gives a global state's property values packed in
// blockSchemas order, property 0 least significant.
var statePacked []uint32

func init() {
	raw, err := base64.StdEncoding.DecodeString(statePackedBlob)
	if err != nil {
		panic("blockstate table: " + err.Error())
	}
	statePacked = make([]uint32, len(raw)/4)
	for i := range statePacked {
		statePacked[i] = uint32(raw[i*4]) | uint32(raw[i*4+1])<<8 | uint32(raw[i*4+2])<<16 | uint32(raw[i*4+3])<<24
	}
}
